const array<long long,13>& rectangle_costs(int id){
 auto found=rectangleSignalCosts.find(id);if(found!=rectangleSignalCosts.end())return found->second;
 array<long long,13> costs;for(int c=0;c<13;c++){unsigned p=0,n=0;for(int i=0;i<certs[c].rows;i++)if(bit(sigs[id].val,rectPos[c][i]))p|=1u<<i;for(int i=0;i<certs[c].cols;i++)if(!bit(sigs[id].val,rectNeg[c][i]))n|=1u<<i;uint64_t key=((uint64_t)p<<21)|n;auto it=rectangleProfiles[c].find(key);if(it==rectangleProfiles[c].end())it=rectangleProfiles[c].emplace(key,rectangle_cost(c,p,n)).first;costs[c]=it->second;}
 return rectangleSignalCosts.emplace(id,costs).first->second;
}
bool rectangle_cut(const vector<int>&state){
 array<long long,13>totals{};for(int id:state){auto&costs=rectangle_costs(id);for(int i=0;i<13;i++)totals[i]+=costs[i];bool allOver=true;for(int i=0;i<13;i++)if(totals[i]<rectTotals[i])allOver=false;if(allOver)return false;}
 for(int ci=0;ci<13;ci++)if(totals[ci]<rectTotals[ci]){rectangleHits[ci]++;
  if(rectangleTrace.is_open()){rectangleTrace<<"{\"event\":\"rectangle\",\"node\":"<<nodes<<",\"remaining\":"<<(state.size()-1)<<",\"matrix\":"<<ci<<",\"total\":"<<rectTotals[ci]<<",\"cost_sum\":"<<totals[ci]<<",\"state\":[";for(size_t j=0;j<state.size();j++){if(j)rectangleTrace<<",";rectangleTrace<<state[j];rectangleTraceSignals.insert(state[j]);}rectangleTrace<<"],\"root_costs\":[";for(size_t j=0;j<state.size();j++){if(j)rectangleTrace<<",";rectangleTrace<<rectangle_costs(state[j])[ci];}rectangleTrace<<"]}"<<'\n';}
  return true;}return false;
}
